<template><view class="page"><view class="row"><view class="title">学习记录</view><text class="badge">最近七天</text></view><view v-if="error" class="card"><view class="error">{{error}}</view><button class="secondary" @click="load">重新加载</button></view><view v-else-if="loading" class="loading">正在加载…</view><EmptyState v-else-if="!plan"/><template v-else-if="data"><view class="muted plan-name">{{plan.examName}}</view><view class="card stats"><view><view class="muted">学习时长</view><view class="big">{{(data.minutes/60).toFixed(1)}}<text> 小时</text></view></view><view><view class="muted">完成任务</view><view class="big">{{data.completedTasks}}<text> 项</text></view></view><view><view class="muted">连续学习</view><view class="big">{{data.streak}}<text> 天</text></view></view></view><view class="card"><view class="section">每日学习时长 <text class="muted">（分钟）</text></view><view class="chart"><view v-for="d in data.week" :key="d.date" class="bar-column"><text class="muted">{{d.minutes}}</text><view class="bar-space"><view class="bar" :style="{height:Math.max(3,d.minutes/max*130)+'px'}"/></view><text class="muted">{{d.date.slice(5)}}</text></view></view></view><view class="card"><view class="section">学习时长分布</view><view v-if="!data.subjects.length" class="muted">完成第一项任务后，这里将记录你的进步。</view><view v-else class="distribution"><view class="donut" :style="{background:donut}"><view class="donut-hole"><view>{{(data.minutes/60).toFixed(1)}}</view><text class="muted">小时</text></view></view><view class="legend"><view v-for="(s,i) in data.subjects" :key="s.name" class="legend-row"><view class="row"><view class="legend-dot" :style="{background:colors[i%colors.length]}"/><text>{{s.name}}</text></view><text>{{Math.round(s.minutes/data.minutes*100)}}%</text></view></view></view></view><view class="muted foot">学习时长根据已完成任务的计划时长统计；连续天数按实际打卡日期计算。</view></template></view></template>
<script setup>
import {ref,computed} from 'vue';import {onShow} from '@dcloudio/uni-app';import {api,current} from '../../api';import EmptyState from '../../components/EmptyState.vue'
const plan=ref(null),data=ref(null),loading=ref(true),error=ref(''),colors=['#1680FF','#25C4C6','#FFB43D','#FE8565','#6BB6FF','#37C591','#EFB268','#527EAE']
const max=computed(()=>Math.max(1,...(data.value?.week||[]).map(d=>d.minutes))),donut=computed(()=>{if(!data.value?.minutes)return '#EAF0F8';let offset=0;return 'conic-gradient('+data.value.subjects.map((s,i)=>{const from=offset;offset+=s.minutes/data.value.minutes*100;return colors[i%colors.length]+' '+from+'% '+offset+'%'}).join(',')+')'})
async function load(){loading.value=true;error.value='';try{plan.value=await current();if(plan.value)data.value=await api.records(plan.value.id)}catch(e){error.value=e.message}finally{loading.value=false}}onShow(load)
</script>
<style scoped>.title{font-size:30rpx}.plan-name{margin:18rpx 0 24rpx}.stats{display:flex;justify-content:space-between;text-align:center;padding:24rpx 20rpx}.stats .big{font-size:43rpx;color:#132B4D;margin-top:10rpx}.stats .big text{font-size:20rpx;font-weight:400}.stats .muted{font-size:22rpx}.section{font-size:27rpx;margin-top:0}.section .muted{font-size:21rpx;font-weight:400}.chart{display:flex;gap:10rpx;justify-content:space-between;align-items:flex-end}.bar-column{flex:1;text-align:center}.bar-column .muted{font-size:19rpx}.bar-space{height:140px;display:flex;align-items:flex-end;justify-content:center;margin:10rpx 0}.bar{width:26rpx;max-height:130px;background:linear-gradient(#1780FF,#70C4FF);border-radius:6rpx 6rpx 0 0}.distribution{display:flex;gap:26rpx;align-items:center}.donut{width:240rpx;height:240rpx;border-radius:50%;padding:32rpx;flex-shrink:0}.donut-hole{border-radius:50%;background:#fff;width:100%;height:100%;display:flex;flex-direction:column;align-items:center;justify-content:center}.donut-hole view{font-size:42rpx;font-weight:800}.legend{flex:1;min-width:0}.legend-row{display:flex;align-items:center;justify-content:space-between;gap:12rpx;margin:14rpx 0;font-size:22rpx}.legend-row .row{gap:10rpx}.legend-dot{width:14rpx;height:14rpx;flex-shrink:0;border-radius:4rpx}.foot{font-size:21rpx}</style>
